solution.solution.py:
def to_number(address):
    value = 0
    for part in address.split("."):
        value = value * 256 + int(part)
    return value

def to_text(number):
    parts = []
    for shift in (24, 16, 8, 0):
        parts.append(str((number >> shift) & 0xFF))
    return ".".join(parts)

def same_network(a, b, prefix):
    drop = 32 - prefix
    return to_number(a) >> drop == to_number(b) >> drop

unitTests:
@test("text to number")
def _():
    check_eq(to_number("0.0.0.0"), 0)
    check_eq(to_number("0.0.1.0"), 256)
    check_eq(to_number("93.184.215.14"), 1572394766)
    check_eq(to_number("255.255.255.255"), 4294967295)

@test("number to text")
def _():
    check_eq(to_text(1572394766), "93.184.215.14")
    check_eq(to_text(0x7F000001), "127.0.0.1")
    check_eq(to_text(0), "0.0.0.0")

@test("same network or not")
def _():
    check(same_network("192.168.1.20", "192.168.1.200", 24))
    check(not same_network("192.168.1.20", "192.168.2.20", 24))
    check(same_network("10.1.2.3", "10.200.0.1", 8))
    check(not same_network("10.0.0.1", "10.0.0.2", 32))
    check(same_network("1.2.3.4", "200.0.0.0", 0))

